export interface TestConfig {
    server: {
        baseUrl: string;
        accessToken: string;
        apiPrefix: string;
    };
    test: {
        timeout: number;
        retries: number;
        concurrent: number;
        iterations: number;
    };
    logging: {
        level: "debug" | "info" | "warn" | "error";
        file?: string;
    };
}

export const DEFAULT_TEST_CONFIG: TestConfig = {
    server: {
        baseUrl: process.env.SYNAPSE_SERVER_URL || "http://10.168.3.50:8008",
        accessToken: process.env.SYNAPSE_ACCESS_TOKEN || "syt_dGVzdHVzZXIx_JwHFHogqHeLtEuPfEGDU_4YyTR4",
        apiPrefix: "",
    },
    test: {
        timeout: 60000,
        retries: 3,
        concurrent: 5,
        iterations: 10,
    },
    logging: {
        level: "info",
    },
};

export function loadTestConfig(overrides?: Partial<TestConfig>): TestConfig {
    return {
        ...DEFAULT_TEST_CONFIG,
        ...overrides,
        server: {
            ...DEFAULT_TEST_CONFIG.server,
            ...(overrides?.server || {}),
        },
        test: {
            ...DEFAULT_TEST_CONFIG.test,
            ...(overrides?.test || {}),
        },
        logging: {
            ...DEFAULT_TEST_CONFIG.logging,
            ...(overrides?.logging || {}),
        },
    };
}

export function validateConfig(config: TestConfig): { valid: boolean; errors: string[] } {
    const errors: string[] = [];

    if (!config.server.baseUrl) {
        errors.push("Server base URL is required");
    }

    if (!config.server.accessToken) {
        errors.push("Server access token is required");
    }

    if (config.test.timeout <= 0) {
        errors.push("Test timeout must be greater than 0");
    }

    if (config.test.retries < 0) {
        errors.push("Test retries must be non-negative");
    }

    if (config.test.concurrent <= 0) {
        errors.push("Test concurrent must be greater than 0");
    }

    if (config.test.iterations <= 0) {
        errors.push("Test iterations must be greater than 0");
    }

    return {
        valid: errors.length === 0,
        errors,
    };
}
